package de.snwiem.jdbx;

import java.io.IOException;
import java.util.Properties;

/** Build metadata shared by Interactive mode and Batch mode. No Spring or terminal dependencies. */
public final class BuildInfo {

	private final Properties properties;

	/** {@code properties} is null when the build metadata file is unavailable. */
	public BuildInfo(Properties properties) {
		this.properties = properties;
	}

	/** Reads the metadata generated by Maven; missing or unreadable metadata is not fatal. */
	public static BuildInfo current() {
		try (var input = BuildInfo.class.getResourceAsStream("/git.properties")) {
			if (input == null) {
				return new BuildInfo(null);
			}
			var properties = new Properties();
			properties.load(input);
			return new BuildInfo(properties);
		}
		catch (IOException e) {
			return new BuildInfo(null);
		}
	}

	/** The Maven project version, without commit information. */
	public String version() {
		String version = properties == null ? null : properties.getProperty("git.build.version");
		return version == null || version.isBlank() ? "unknown version" : version;
	}

	public String versionText() {
		String version = version();
		if (version.equals("unknown version")) {
			return "unknown version";
		}
		String commit = properties.getProperty("git.commit.id.abbrev");
		String dirty = Boolean.parseBoolean(properties.getProperty("git.dirty")) ? "-dirty" : "";
		return version + " (" + (commit == null || commit.isBlank() ? "unknown" : commit + dirty) + ")";
	}
}
